        fx = -35.0  # Ensure this is strictly less than -34.0
        fy = 100.0 * (ty - y) - 20.0 * vyd + w_comp

        # Check if in activation zone and speed is acceptable
        if (cfg["act_lo"] <= x <= cfg["act_hi"]) and (math.hypot(vxd, vyd) < BACKWARD_SPEED_MAX):
            state["unlock_steps"] += 1
        else:
            state["unlock_steps"] = 0

        # If unlock conditions are met for 5 steps
        if state["unlock_steps"] >= 5:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Navigate around obstacles using whisker sensors
        if front < 0.3:  # Close to a wall in front
